SELECT id, full_name, email, dept_id, job_title, hire_date, is_remote, level, SUM(salary) OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, RANK() OVER (PARTITION BY job_title, dept_id ORDER BY salary) AS salary_rank, ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY salary DESC, id) AS row_seq, DENSE_RANK() OVER (PARTITION BY MONTH(hire_date) ORDER BY salary DESC) AS salary_dense_rank, AVG(salary) OVER (PARTITION BY DATE_TRUNC('week', hire_date), level ORDER BY salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3 FROM employees
